/**
 * Freshness — the "worth engaging right now" signal shared by both sensors.
 *
 * An opportunity is FRESH when the source post is recent enough that jumping in
 * is still timely AND we discovered it recently. This is the single source of
 * truth for the "NEW" badge in the extension options list and the dashboard
 * queue — it is deliberately decoupled from `status` (which just means triaged
 * vs. not).
 */

/** Source post age ceiling — older than this and the moment has passed. */
export const FRESH_PUBLISHED_HOURS = 4;

/** Discovery-age guard — we should also have found it recently. */
export const FRESH_FOUND_HOURS = 24;

/**
 * @param {{ publishedAt?: string|null, createdAt?: string }} opp
 * @param {number} nowMs — current epoch ms; pass Date.now() from the caller
 *   (this module stays pure so vendored copies never call Date.now themselves).
 * @returns {boolean}
 */
export function isFresh(opp, nowMs) {
  if (!opp || !opp.publishedAt) return false;
  const pub = Date.parse(opp.publishedAt);
  if (Number.isNaN(pub)) return false;
  if (nowMs - pub > FRESH_PUBLISHED_HOURS * 3600e3) return false;
  // Discovery is always >= publish time, so this guard rarely binds; it exists
  // so a stale row with a fresh-looking publishedAt can't light up the badge.
  const found = Date.parse(opp.createdAt);
  return Number.isNaN(found) || nowMs - found <= FRESH_FOUND_HOURS * 3600e3;
}
